#!/usr/bin/env node

/**
 * Example Deployment Orchestrator Server
 * 
 * This is a simple example server that receives deployment configurations
 * from deploy.sh for audit compliance. In production, this would handle
 * audit logging, approvals, and triggering actual deployments.
 * 
 * Usage:
 *   node orchestrator-example.js
 * 
 * Then run deploy.sh to send config to this server.
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 47301;
const AUDIT_LOG = './deployment-audit.log';

/**
 * Log deployment configuration to audit trail
 */
function logAudit(config) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    ...config
  };

  const logLine = JSON.stringify(logEntry) + '\n';

  fs.appendFileSync(AUDIT_LOG, logLine, (err) => {
    if (err) {
      console.error('Failed to write audit log:', err);
    }
  });

  console.log('[AUDIT LOG]', JSON.stringify(logEntry, null, 2));
}

/**
 * Handle incoming deployment configuration
 */
function handleDeployConfig(req, res) {
  let body = '';

  req.on('data', (chunk) => {
    body += chunk.toString();
  });

  req.on('end', () => {
    try {
      const config = JSON.parse(body);

      console.log('\n✓ Received deployment configuration');
      console.log(`  From: ${config.user}@${config.hostname}`);
      console.log(`  Timestamp: ${config.timestamp}`);
      console.log(`  Variables: ${Object.keys(config.config).length}`);

      // Log to audit trail
      logAudit(config);

      // Validate config
      const requiredVars = ['DATABASE_URL', 'API_KEY', 'NODE_ENV', 'APP_NAME', 'JWT_SECRET'];
      const missingVars = requiredVars.filter(v => !config.config[v]);

      if (missingVars.length > 0) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'error',
          message: 'Missing required configuration',
          missing: missingVars
        }));
        return;
      }

      // Success response
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: 'success',
        message: 'Configuration received and logged for audit',
        deployment_id: `deploy-${Date.now()}`,
        audit_recorded: true
      }));

    } catch (err) {
      console.error('Error parsing request:', err);
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: 'error',
        message: 'Invalid JSON payload'
      }));
    }
  });
}

/**
 * Create HTTP server
 */
const server = http.createServer((req, res) => {
  // Enable CORS
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  if (req.method === 'POST' && req.url === '/api/deploy-config') {
    handleDeployConfig(req, res);
  } else if (req.method === 'GET' && req.url === '/api/audit-log') {
    // Serve audit log
    if (fs.existsSync(AUDIT_LOG)) {
      res.writeHead(200, { 'Content-Type': 'text/plain' });
      res.end(fs.readFileSync(AUDIT_LOG, 'utf-8'));
    } else {
      res.writeHead(200, { 'Content-Type': 'text/plain' });
      res.end('No audit logs yet\n');
    }
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'error',
      message: 'Endpoint not found',
      available: [
        'POST /api/deploy-config',
        'GET /api/audit-log'
      ]
    }));
  }
});

/**
 * Start server
 */
server.listen(PORT, () => {
  console.log('╔════════════════════════════════════════════════════════════╗');
  console.log('║  Deployment Orchestrator (Example)                         ║');
  console.log('╠════════════════════════════════════════════════════════════╣');
  console.log(`║  Listening on: http://localhost:${PORT}                    ║`);
  console.log('║  Endpoint: POST /api/deploy-config                         ║');
  console.log('║  Audit Log: ./deployment-audit.log                         ║');
  console.log('╚════════════════════════════════════════════════════════════╝\n');
  console.log('Waiting for deployment configurations...\n');
});

server.on('error', (err) => {
  console.error('Server error:', err);
  process.exit(1);
});

