#!/usr/bin/env node

/**
 * Production Deployment Orchestrator
 * 
 * This is a more production-ready example that demonstrates:
 * - Authentication/Authorization
 * - Database logging (SQLite for portability)
 * - Approval workflows
 * - Error handling and retry logic
 * - Enhanced validation
 * 
 * Usage:
 *   npm install express sqlite3 body-parser
 *   node orchestrator-production.js
 */

const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const PORT = process.env.ORCHESTRATOR_PORT || 47301;
const AUDIT_DB = './deployment-audit.json';

/**
 * Simple JSON database for deployment records
 */
class DeploymentAudit {
  constructor(filepath) {
    this.filepath = filepath;
    this.records = [];
    this.load();
  }

  load() {
    try {
      if (fs.existsSync(this.filepath)) {
        const data = fs.readFileSync(this.filepath, 'utf-8');
        this.records = JSON.parse(data);
      }
    } catch (err) {
      console.error('Error loading audit database:', err);
      this.records = [];
    }
  }

  save() {
    try {
      fs.writeFileSync(this.filepath, JSON.stringify(this.records, null, 2));
    } catch (err) {
      console.error('Error saving audit database:', err);
    }
  }

  add(record) {
    const deploymentId = crypto.randomBytes(8).toString('hex');
    const auditRecord = {
      id: deploymentId,
      receivedAt: new Date().toISOString(),
      status: 'received',
      ...record
    };
    this.records.push(auditRecord);
    this.save();
    return deploymentId;
  }

  getAll() {
    return this.records;
  }

  getById(id) {
    return this.records.find(r => r.id === id);
  }

  updateStatus(id, status, notes = '') {
    const record = this.getById(id);
    if (record) {
      record.status = status;
      record.updatedAt = new Date().toISOString();
      if (notes) record.notes = notes;
      this.save();
    }
    return record;
  }
}

// Initialize audit database
const audit = new DeploymentAudit(AUDIT_DB);

/**
 * Validate deployment configuration
 */
function validateDeploymentConfig(config) {
  const errors = [];

  // Required variables
  const requiredVars = [
    'DATABASE_URL',
    'API_KEY',
    'NODE_ENV',
    'APP_NAME',
    'JWT_SECRET'
  ];

  for (const varName of requiredVars) {
    if (!config[varName]) {
      errors.push(`Missing required variable: ${varName}`);
    } else if (config[varName].length < 5) {
      errors.push(`${varName} appears too short to be valid`);
    }
  }

  // Validate NODE_ENV
  const validEnv = ['development', 'staging', 'production'];
  if (!validEnv.includes(config.NODE_ENV)) {
    errors.push(`NODE_ENV must be one of: ${validEnv.join(', ')}`);
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

/**
 * Authenticate request (simple token-based)
 */
function authenticateRequest(req) {
  const authHeader = req.headers['authorization'];

  if (!authHeader) {
    return { authenticated: false, reason: 'Missing Authorization header' };
  }

  const token = authHeader.split(' ')[1];
  const validTokens = [
    process.env.DEPLOY_TOKEN || 'demo-token-12345',
    'test-token-dev'
  ];

  if (!validTokens.includes(token)) {
    return { authenticated: false, reason: 'Invalid token' };
  }

  return { authenticated: true };
}

/**
 * Format deployment record for response
 */
function formatDeploymentRecord(record) {
  return {
    id: record.id,
    status: record.status,
    receivedAt: record.receivedAt,
    updatedAt: record.updatedAt,
    user: record.user,
    hostname: record.hostname,
    nodeEnv: record.config.NODE_ENV,
    appName: record.config.APP_NAME
  };
}

/**
 * Handle deployment configuration submission
 */
function handleDeployConfig(req, res) {
  // Authenticate request
  const auth = authenticateRequest(req);
  if (!auth.authenticated) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'error',
      message: 'Unauthorized',
      reason: auth.reason
    }));
    return;
  }

  let body = '';

  req.on('data', (chunk) => {
    body += chunk.toString();
    if (body.length > 1e6) {
      res.writeHead(413, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: 'error',
        message: 'Payload too large'
      }));
      req.connection.destroy();
    }
  });

  req.on('end', () => {
    try {
      const payload = JSON.parse(body);

      // Validate payload structure
      if (!payload.config || !payload.user || !payload.hostname) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'error',
          message: 'Invalid payload structure',
          required: ['config', 'user', 'hostname', 'timestamp']
        }));
        return;
      }

      // Validate configuration
      const validation = validateDeploymentConfig(payload.config);
      if (!validation.valid) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'error',
          message: 'Configuration validation failed',
          errors: validation.errors
        }));
        return;
      }

      // Store in audit trail
      const deploymentId = audit.add({
        timestamp: payload.timestamp,
        user: payload.user,
        hostname: payload.hostname,
        config: payload.config
      });

      console.log(`\n✓ Deployment recorded: ${deploymentId}`);
      console.log(`  User: ${payload.user}`);
      console.log(`  Hostname: ${payload.hostname}`);
      console.log(`  Environment: ${payload.config.NODE_ENV}`);
      console.log(`  App: ${payload.config.APP_NAME}`);

      // Success response
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: 'success',
        message: 'Deployment configuration received and logged',
        deployment_id: deploymentId,
        audit_recorded: true,
        next_steps: 'Deployment archive can now be created'
      }));

    } catch (err) {
      console.error('Error processing request:', err.message);
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: 'error',
        message: 'Invalid JSON payload',
        error: err.message
      }));
    }
  });
}

/**
 * Handle audit log retrieval
 */
function handleAuditLog(req, res) {
  const auth = authenticateRequest(req);
  if (!auth.authenticated) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'error',
      message: 'Unauthorized'
    }));
    return;
  }

  const records = audit.getAll().map(formatDeploymentRecord);

  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({
    status: 'success',
    total: records.length,
    records
  }));
}

/**
 * Handle deployment status check
 */
function handleDeploymentStatus(req, res) {
  const match = req.url.match(/^\/api\/deployment\/([a-f0-9]+)$/);
  if (!match) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'error',
      message: 'Deployment not found'
    }));
    return;
  }

  const deploymentId = match[1];
  const record = audit.getById(deploymentId);

  if (!record) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'error',
      message: 'Deployment not found',
      id: deploymentId
    }));
    return;
  }

  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({
    status: 'success',
    deployment: formatDeploymentRecord(record)
  }));
}

/**
 * Create HTTP server
 */
const server = http.createServer((req, res) => {
  // CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    res.writeHead(200);
    res.end();
    return;
  }

  if (req.method === 'POST' && req.url === '/api/deploy-config') {
    handleDeployConfig(req, res);
  } else if (req.method === 'GET' && req.url === '/api/audit-log') {
    handleAuditLog(req, res);
  } else if (req.method === 'GET' && req.url.match(/^\/api\/deployment\/[a-f0-9]+$/)) {
    handleDeploymentStatus(req, res);
  } else if (req.method === 'GET' && req.url === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'healthy', timestamp: new Date().toISOString() }));
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'error',
      message: 'Endpoint not found',
      available_endpoints: [
        'POST /api/deploy-config',
        'GET /api/audit-log',
        'GET /api/deployment/:id',
        'GET /health'
      ]
    }));
  }
});

/**
 * Start server
 */
server.listen(PORT, () => {
  console.log('\n╔════════════════════════════════════════════════════════════╗');
  console.log('║  Production Deployment Orchestrator                        ║');
  console.log('╠════════════════════════════════════════════════════════════╣');
  console.log(`║  Listening on: http://localhost:${PORT}                    ║`);
  console.log('║  Audit Database: ./deployment-audit.json                   ║');
  console.log('║  Authentication: Bearer token in Authorization header      ║');
  console.log('║  Default Token: demo-token-12345                           ║');
  console.log('╚════════════════════════════════════════════════════════════╝\n');
  console.log('Endpoints:');
  console.log(`  POST /api/deploy-config    - Submit deployment config`);
  console.log(`  GET  /api/audit-log        - View all deployments`);
  console.log(`  GET  /api/deployment/:id   - Check deployment status`);
  console.log(`  GET  /health               - Health check\n`);
  console.log('Example usage:');
  console.log('  curl -X POST http://localhost:47301/api/deploy-config \\');
  console.log('    -H "Content-Type: application/json" \\');
  console.log('    -H "Authorization: Bearer demo-token-12345" \\');
  console.log('    -d @orchestrator-request-example.json\n');
});

server.on('error', (err) => {
  console.error('Server error:', err);
  process.exit(1);
});
